<script setup lang="ts">import { computed } from 'vue';import { useSettingsStore } from '../stores/settings.store';const s=useSettingsStore();const url=computed(()=>{if(s.data.background!=='photo')return'';const day=new Date().toISOString().slice(0,10);const seed=s.data.photoSeed==='daily'?`istante-${day}`:s.data.photoSeed||'istante';return `https://picsum.photos/seed/${encodeURIComponent(seed)}/1920/1080`})</script><template><div v-if="url" class="photo-bg" :style="{backgroundImage:`url(${url})`}"/></template>
